WITH transactions_by_account AS (SELECT account_id, ROUND((100 * SUM(CASE WHEN merchant = 'Lazada' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_lazada, COUNT(amount) AS amount_count FROM transactions WHERE txn_type NOT IN ('CREDIT', 'FEE', 'DEBIT') GROUP BY account_id) SELECT a.id, a.opened_date, a.customer_id, tba.pct_lazada, tba.amount_count FROM accounts a INNER JOIN transactions_by_account tba ON a.id = tba.account_id ORDER BY a.id DESC, tba.amount_count LIMIT 5
